class NewsFeedManager {
    private let newsAPI = NewsAPI()
    private let userDefaults = UserDefaults.standard

    func getLocalizedNewsForUser(user: User) -> [LocalizedNews] {
        // 1. Get user's demographics from userDefaults
        let demographics = userDefaults.dictionary(forKey: "demographics") as? [String: Any]
        // 2. Use demographics to query the newsAPI for localized news updates
        let localizedNews = newsAPI.getLocalizedNewsForUser(demographics: demographics!)
        // 3. Return the localized news updates
        return localizedNews
    }
